//! Cross-component contract replay: `contract/facade-requests.json`
//! records the REAL HTTP requests the published facade bytes emit for KV
//! put/get/list/delete and R2 put/head/get/list/delete (generated by
//! `contract/gen-facade-requests.mjs`). This test rebuilds the matching
//! `compute.desired` view from the fixture's props, replays every request
//! against the in-memory provider through the real router, and asserts
//! (a) the request is accepted and (b) the provider's response decodes to
//! the same semantic result the facade produced — the bidirectional check
//! that facade and provider implement the same protocol.
//!
//! Regenerate the fixture with
//! `node contract/gen-facade-requests.mjs`;
//! drift fails here via `--check` on the node side and via this replay
//! on the Rust side.

mod support;

use axum::body::Body;
use axum::http::{Request, StatusCode};
use base64::{engine::general_purpose::STANDARD, Engine};
use std::sync::Arc;
use support::*;
use tower::ServiceExt;
use vrt_provider::cursor::CursorSigner;
use vrt_provider::kv::{self, MemoryKvProvider};
use vrt_provider::r2::MemoryR2Provider;
use vrt_provider::server::{tenant_router, TenantService};

const FIXTURE: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../contract/facade-requests.json"
));

/// Build the provider view the fixture's props authorize against: same
/// worker, version, digest, both bindings, revision == specGeneration.
fn contract_service(fixture: &serde_json::Value) -> Arc<TenantService> {
    let f = support::fixture();
    let kv = &fixture["props"]["kv"];
    let r2 = &fixture["props"]["r2"];
    let (kv_worker, kv_name) = binding_parts(kv["bindingId"].as_str().unwrap());
    let (r2_worker, r2_name) = binding_parts(r2["bindingId"].as_str().unwrap());
    assert_eq!(kv_worker, r2_worker);
    assert_eq!(kv["workerId"].as_str().unwrap(), kv_worker);
    assert_eq!(kv["versionId"], r2["versionId"]);
    assert_eq!(kv["descriptorSha256"], r2["descriptorSha256"]);
    let revision = kv["resourceSpecGeneration"].as_u64().unwrap();
    assert_eq!(revision, r2["resourceSpecGeneration"].as_u64().unwrap());

    let payload = desired(
        revision,
        vec![tenant(
            kv["instanceId"].as_str().unwrap(),
            vec![worker(
                kv_worker,
                kv["versionId"].as_str().unwrap(),
                kv["descriptorSha256"].as_str().unwrap(),
                vec![
                    kv_binding_perms(
                        kv_name,
                        kv["namespaceResourceId"].as_str().unwrap(),
                        kv["permissions"]["read"].as_bool().unwrap(),
                        kv["permissions"]["write"].as_bool().unwrap(),
                    ),
                    r2_binding_perms(
                        r2_name,
                        r2["namespaceResourceId"].as_str().unwrap(),
                        r2["permissions"]["read"].as_bool().unwrap(),
                        r2["permissions"]["write"].as_bool().unwrap(),
                    ),
                ],
            )],
        )],
    );
    let store = store_with(&f, &payload, revision);
    Arc::new(TenantService {
        tenant_id: kv["instanceId"].as_str().unwrap().to_string(),
        authorizer: Arc::new(authorizer(store, 30_000)),
        kv: Some(Arc::new(MemoryKvProvider::new())),
        assets: None,
        r2: Some(Arc::new(MemoryR2Provider::new())),
        signer: Arc::new(CursorSigner::new(b"cursor-secret")),
        r2_max_object_bytes: 1024 * 1024,
        permits: Arc::new(tokio::sync::Semaphore::new(64)),
        global_permits: Arc::new(tokio::sync::Semaphore::new(512)),
        body_read_timeout: std::time::Duration::from_secs(30),
        d1: None,
        queue: None,
        pg: None,
    })
}

fn binding_parts(binding_id: &str) -> (&str, &str) {
    binding_id
        .split_once('~')
        .expect("bindingId must be <workerId>~<name>")
}

fn expect_err_none(headers: &axum::http::HeaderMap, label: &str) {
    assert!(
        headers.get("x-open-compute-error-code").is_none(),
        "{label}: unexpected error-code header"
    );
}

#[tokio::test]
async fn facade_requests_replay_against_provider() {
    let fixture: serde_json::Value = serde_json::from_str(FIXTURE).unwrap();
    assert_eq!(fixture["schemaVersion"], 1);
    let svc = contract_service(&fixture);
    let router = tenant_router(svc);

    let labels: Vec<String> = fixture["requests"]
        .as_array()
        .unwrap()
        .iter()
        .map(|r| r["label"].as_str().unwrap().to_string())
        .collect();
    assert_eq!(
        labels,
        [
            "kv-put",
            "kv-get",
            "kv-list",
            "kv-delete",
            "r2-put",
            "r2-head",
            "r2-get",
            "r2-list",
            "r2-delete"
        ],
        "fixture must cover the contract op set"
    );

    for req in fixture["requests"].as_array().unwrap() {
        let label = req["label"].as_str().unwrap();
        let body = STANDARD
            .decode(req["bodyBase64"].as_str().unwrap())
            .unwrap();
        let mut builder = Request::builder()
            .method(req["method"].as_str().unwrap())
            .uri(format!(
                "http://binding-backend{}",
                req["path"].as_str().unwrap()
            ));
        for (name, value) in req["headers"].as_object().unwrap() {
            builder = builder.header(name.as_str(), value.as_str().unwrap());
        }
        // Per-call header regenerated by the facade; a fixed canonical UUID
        // stands in (the fixture deliberately omits it).
        builder = builder.header("x-open-compute-request-id", REQUEST_ID);
        let response = router
            .clone()
            .oneshot(builder.body(Body::from(body)).unwrap())
            .await
            .expect("router infallible");
        let expected_status = req["expect"]["status"].as_u64().unwrap() as u16;
        assert_eq!(
            response.status().as_u16(),
            expected_status,
            "{label}: status"
        );
        expect_err_none(response.headers(), label);
        let body = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        check_decoded(label, &req["expect"]["decoded"], &body);
    }
}

/// Decode the provider response with the same wire rules the facade
/// applies and compare the semantic result recorded by the generator.
fn check_decoded(label: &str, decoded: &serde_json::Value, body: &[u8]) {
    match label {
        "kv-put" | "kv-delete" => {
            assert!(body.is_empty(), "{label}: ack frames carry no bytes");
        }
        "kv-get" => {
            assert_eq!(&body[..4], b"KVS1", "{label}: KVS1 magic");
            let (entry, consumed) = kv::decode_entry(&body[4..]).expect("decode entry");
            assert_eq!(consumed, body.len() - 4, "{label}: trailing bytes");
            let entry = entry.expect("{label}: entry present");
            assert_eq!(entry.value, decoded.as_str().unwrap().as_bytes());
        }
        "kv-list" => {
            let page: serde_json::Value = serde_json::from_slice(body).unwrap();
            let names: Vec<&str> = page["keys"]
                .as_array()
                .unwrap()
                .iter()
                .map(|k| k["name"].as_str().unwrap())
                .collect();
            let expected: Vec<&str> = decoded["keys"]
                .as_array()
                .unwrap()
                .iter()
                .map(|k| k["name"].as_str().unwrap())
                .collect();
            assert_eq!(names, expected, "{label}: key names");
            assert_eq!(
                page["list_complete"].as_bool().unwrap(),
                decoded["list_complete"].as_bool().unwrap(),
                "{label}: list_complete"
            );
        }
        "r2-put" | "r2-head" => {
            let meta: serde_json::Value = serde_json::from_slice(body).unwrap();
            assert_eq!(
                meta["key"].as_str().unwrap(),
                decoded["key"].as_str().unwrap()
            );
            assert_eq!(
                meta["size"].as_u64().unwrap(),
                decoded["size"].as_u64().unwrap(),
                "{label}: size"
            );
        }
        "r2-get" => {
            let header_len = u32::from_be_bytes(body[..4].try_into().unwrap()) as usize;
            let frame: serde_json::Value =
                serde_json::from_slice(&body[4..4 + header_len]).unwrap();
            let meta = &frame["meta"];
            assert_eq!(
                meta["key"].as_str().unwrap(),
                decoded["key"].as_str().unwrap()
            );
            assert_eq!(
                meta["size"].as_u64().unwrap(),
                decoded["size"].as_u64().unwrap()
            );
            assert_eq!(frame["hasBody"].as_bool().unwrap(), true);
            assert_eq!(
                &body[4 + header_len..],
                decoded["text"].as_str().unwrap().as_bytes(),
                "{label}: body bytes"
            );
        }
        "r2-list" => {
            let page: serde_json::Value = serde_json::from_slice(body).unwrap();
            let keys: Vec<&str> = page["objects"]
                .as_array()
                .unwrap()
                .iter()
                .map(|o| o["key"].as_str().unwrap())
                .collect();
            let expected: Vec<&str> = decoded["keys"]
                .as_array()
                .unwrap()
                .iter()
                .map(|k| k.as_str().unwrap())
                .collect();
            assert_eq!(keys, expected, "{label}: object keys");
            assert_eq!(
                page["truncated"].as_bool().unwrap(),
                decoded["truncated"].as_bool().unwrap()
            );
            let prefixes: Vec<&str> = page["delimitedPrefixes"]
                .as_array()
                .unwrap()
                .iter()
                .map(|p| p.as_str().unwrap())
                .collect();
            let expected_p: Vec<&str> = decoded["delimitedPrefixes"]
                .as_array()
                .unwrap()
                .iter()
                .map(|p| p.as_str().unwrap())
                .collect();
            assert_eq!(prefixes, expected_p, "{label}: delimitedPrefixes");
        }
        "r2-delete" => {
            assert!(body.is_empty(), "{label}: 204 carries no bytes");
        }
        other => panic!("unhandled contract label {other}"),
    }
}

/// The replay must also reject mutations that break the contract: the
/// same recorded request with a forged resource id is denied.
#[tokio::test]
async fn contract_replay_still_denies_forged_identity() {
    let fixture: serde_json::Value = serde_json::from_str(FIXTURE).unwrap();
    let svc = contract_service(&fixture);
    let router = tenant_router(svc);
    let req = &fixture["requests"].as_array().unwrap()[1]; // kv-get
    let body = STANDARD
        .decode(req["bodyBase64"].as_str().unwrap())
        .unwrap();
    let mut builder = Request::builder()
        .method(req["method"].as_str().unwrap())
        .uri(format!(
            "http://binding-backend{}",
            req["path"].as_str().unwrap()
        ));
    for (name, value) in req["headers"].as_object().unwrap() {
        let v = if name.as_str() == "x-open-compute-namespace-resource-id" {
            "forged-namespace"
        } else {
            value.as_str().unwrap()
        };
        builder = builder.header(name.as_str(), v);
    }
    builder = builder.header("x-open-compute-request-id", REQUEST_ID);
    let response = router
        .oneshot(builder.body(Body::from(body)).unwrap())
        .await
        .expect("router infallible");
    assert_eq!(response.status(), StatusCode::FORBIDDEN);
}
